// ============================================================
// Period Statistics Builder —— 按时间窗口统计Ticket_Main
// 和Day43 Dashboard的Statistics Builder思路一样（跨条目汇总），
// 区别是这次要先按period参数算出一个时间窗口，
// 只统计"创建时间落在这个窗口里"的工单，而不是全部历史工单
// ============================================================

// 从Execute Workflow Trigger节点跨节点取出调用方传入的period参数
// 之所以要跨节点取，是因为当前节点前面接的是Read Ticket_Main，
// 它的输出是工单数据，不带period这个字段，period还留在最初的触发节点里
const period = $('When Executed by Another Workflow').first().json.period;

// 拿到"现在"这个时间点，作为窗口的结束时间
const now = new Date();

// 声明窗口起始时间变量，先给个默认值，下面按period具体计算
let windowStart;

// 根据period参数，决定统计窗口从什么时候开始算
if (period === "day") {
  // 今天0点：把"现在"的时分秒都清零，只留年月日
  windowStart = new Date(now.getFullYear(), now.getMonth(), now.getDate());
} else if (period === "week") {
  // 本周一0点：now.getDay()返回0~6（0是周日），用来倒推回本周一
  // (now.getDay() + 6) % 7 的意思是：把"周日=0"换算成"距离周一有几天"
  const dayOfWeek = (now.getDay() + 6) % 7;
  windowStart = new Date(now.getFullYear(), now.getMonth(), now.getDate() - dayOfWeek);
} else {
  // 默认按month处理：本月1号0点
  windowStart = new Date(now.getFullYear(), now.getMonth(), 1);
}

// 拿到Read Ticket_Main传来的全部工单数据
const allTickets = $input.all();

// 声明计数器，和Day43 Dashboard的Statistics Builder同一套逻辑
let total_ticket = 0;
let closed_ticket = 0;
let overdue_ticket = 0;
let reminder_count = 0;
let escalation_count = 0;

for (const ticket of allTickets) {
  const data = ticket.json;

  // 只统计"创建时间落在这个窗口里"的工单，是本次和Day43最大的区别
  const createTime = new Date(data.create_time);
  if (createTime < windowStart || createTime > now) {
    continue;   // continue的意思是"跳过这一条，直接看下一条"，不计入统计
  }

  total_ticket++;

  if (data.status === "Closed") {
    closed_ticket++;
  }

  if (data.due_time && data.status !== "Closed") {
    const dueTime = new Date(data.due_time);
    if (dueTime < now) {
      overdue_ticket++;
    }
  }

  reminder_count += Number(data.reminder_count) || 0;

  if (data.escalation_status === "escalated") {
    escalation_count++;
  }
}

const open_ticket = total_ticket - closed_ticket;

// sla_rate计算方式和Day43一致，同样要兜底total_ticket=0的情况
const sla_rate = total_ticket === 0
  ? 100
  : Math.round(((total_ticket - overdue_ticket) / total_ticket) * 100);

// 用toISOString().slice(0,10)把日期对象转成"yyyy-MM-dd"格式的文本
// 方便写进Google Sheets时是好读的日期字符串，而不是一串时间戳
return [
  {
    json: {
      period_type: period,
      period_start: windowStart.toISOString().slice(0, 10),
      period_end: now.toISOString().slice(0, 10),
      total_ticket,
      closed_ticket,
      open_ticket,
      overdue_ticket,
      reminder_count,
      escalation_count,
      sla_rate
    }
  }
];
